STRATA_DATA = [{"type":"Stratum","register":"Plinth","register_id":1,"elevation_m":3.2,"plate_count":1,"coverage":0.063},{"type":"Stratum","register":"Course","register_id":2,"elevation_m":6.4,"plate_count":8,"coverage":0.354},{"type":"Stratum","register":"Mid","register_id":3,"elevation_m":9.6,"plate_count":9,"coverage":0.198},{"type":"Stratum","register":"Cornice","register_id":4,"elevation_m":12.8,"plate_count":8,"coverage":0.108},{"type":"Stratum","register":"Attic","register_id":5,"elevation_m":16,"plate_count":12,"coverage":0.237},{"type":"Stratum","register":"Crown","register_id":6,"elevation_m":19.2,"plate_count":3,"coverage":0.04}]

print(f"Plates:{len(PLATES_DATA)}  Fins:{len(FINS_DATA)}  GraphNodes:{len(NODES_DATA)}  GraphEdges:{len(EDGES_DATA)}")

# ---- HELPERS -------------------------------------------------------
def v3(pt): return Vertex.ByCoordinates(float(pt[0]), float(pt[1]), float(pt[2]))

def centroid_key(x, y, z, tol=0.05):
    return (round(x/tol)*tol, round(y/tol)*tol, round(z/tol)*tol)

def make_dict(d):
    keys = [str(k) for k in d.keys()]
    vals = [v if isinstance(v,(int,float,bool,str)) else str(v) for v in d.values()]
    return Dictionary.ByKeysValues(keys, vals)

def get_val(topo, key):
    d = Topology.Dictionary(topo)
    return Dictionary.ValueAtKey(d, key) if d else None

def pl_name(r):
    names = ["Datum","Plinth","Course","Mid","Cornice","Attic","Crown","Ridge","Spire","Apex"]
    return names[r] if r < len(names) else f"R{r}"

def cuboid_cell(mn, mx):
    x0,y0,z0 = float(mn[0]),float(mn[1]),float(mn[2])
    x1,y1,z1 = float(mx[0]),float(mx[1]),float(mx[2])
    faces = [
        Face.ByVertices([v3([x0,y0,z0]),v3([x1,y0,z0]),v3([x1,y1,z0]),v3([x0,y1,z0])]),
        Face.ByVertices([v3([x0,y0,z1]),v3([x1,y0,z1]),v3([x1,y1,z1]),v3([x0,y1,z1])]),
        Face.ByVertices([v3([x0,y0,z0]),v3([x1,y0,z0]),v3([x1,y0,z1]),v3([x0,y0,z1])]),
        Face.ByVertices([v3([x0,y1,z0]),v3([x1,y1,z0]),v3([x1,y1,z1]),v3([x0,y1,z1])]),
        Face.ByVertices([v3([x0,y0,z0]),v3([x0,y1,z0]),v3([x0,y1,z1]),v3([x0,y0,z1])]),
        Face.ByVertices([v3([x1,y0,z0]),v3([x1,y1,z0]),v3([x1,y1,z1]),v3([x1,y0,z1])]),
    ]
    return Cell.ByFaces([f for f in faces if f], tolerance=TOL)

# ---- STEP 1: Build plate Cells -------------------------------------
print("\nStep 1 - Building plate Cells...")
cells, cell_centroids = [], {}
for pl in PLATES_DATA:
    c = cuboid_cell(pl["bbox_min"], pl["bbox_max"])
    if not c: continue
    cells.append(c)
    cx,cy,cz = pl["centroid"]
    cell_centroids[centroid_key(cx,cy,cz)] = pl["dict"]
print(f"  Built {len(cells)} Cells")

# ---- STEP 2: Cluster (layered plates) ------------------------------
print("\nStep 2 - Clustering...")
cluster = Cluster.ByTopologies(cells) if cells else None
merged  = Topology.SelfMerge(cluster, tolerance=TOL) if cluster else None
print(f"  Clustered {len(cells)} plates")

# ---- STEP 3: Assign Dicts to Cells ---------------------------------
print("\nStep 3 - Assigning Dictionaries to Cells...")
n_assigned = 0
for c in cells:
    ctr = Topology.Centroid(c)
    ck = centroid_key(Vertex.X(ctr), Vertex.Y(ctr), Vertex.Z(ctr))
    payload = cell_centroids.get(ck)
    if payload: Topology.SetDictionary(c, make_dict(payload)); n_assigned += 1
print(f"  Assigned {n_assigned}/{len(cells)} Cells")

# ---- STEP 4: Build Fin Faces ---------------------------------------
print("\nStep 4 - Building Fin Faces...")
fin_faces = []
for fn in FINS_DATA:
    face = Face.ByVertices([v3(p) for p in fn["verts"]])
    if not face: continue
    Topology.SetDictionary(face, make_dict(fn["dict"]))
    fin_faces.append(face)
print(f"  Built {len(fin_faces)} Fin Faces ({sum(1 for f in FINS_DATA if f['dict'].get('reveal'))} reveals)")

# ---- STEP 5-6: Build Graph -----------------------------------------
print("\nStep 5-6 - Building Graph...")
gverts, vkey = [], {}
for nd in NODES_DATA:
    v = v3(nd["centroid"]); gverts.append(v); vkey[nd["id"]] = v
gedges = []
for e in EDGES_DATA:
    a, b = vkey.get(e["from"]), vkey.get(e["to"])
    if a is None or b is None: continue
    ed = Edge.ByStartVertexEndVertex(a, b, tolerance=TOL)
    if ed:
        Topology.SetDictionary(ed, make_dict(e["dict"]))
        gedges.append(ed)
g = Graph.ByVerticesEdges(gverts, gedges)
print(f"  Graph: {len(Graph.Vertices(g))} vertices, {len(Graph.Edges(g))} edges")

# ---- STEP 7: Assign Dicts to Graph vertices ------------------------
print("\nStep 7 - Assigning Dictionaries to Graph vertices...")
node_lkp = {}
for nd in NODES_DATA:
    cx,cy,cz = nd["centroid"]; node_lkp[centroid_key(cx,cy,cz)] = nd["dict"]
n_gv = 0
for gv in Graph.Vertices(g):
    ck = centroid_key(Vertex.X(gv), Vertex.Y(gv), Vertex.Z(gv))
    payload = node_lkp.get(ck)
    if payload: Topology.SetDictionary(gv, make_dict(payload)); n_gv += 1
print(f"  Assigned {n_gv}/{len(gverts)} Graph vertices")

# ---- STEP 8: GOVERNANCE ANALYSIS -----------------------------------
print("\n"+"="*58)
print("TECTONIC GOVERNANCE ANALYSIS")
print("="*58)

regs = sorted({pl["dict"]["register_id"] for pl in PLATES_DATA})

# Gov-0: Stratum presence — every used register carries plates
print("\n[Gov-0] Stratum Continuity")
by_reg = defaultdict(int)
for pl in PLATES_DATA: by_reg[pl["dict"]["register_id"]] += 1
for r in regs: print(f"  Register {r} ({pl_name(r)}): {by_reg[r]} plates")
grounded = 0 in by_reg
print(f"  Datum (register 0) present: {grounded}")

# Gov-1: Fin support — stepped/reveal adjacencies backed by a Fin
print("\n[Gov-1] Fin Support")
stepped = [e for e in EDGES_DATA if e["dict"]["relation"] in ("stepped","reveal")]
print(f"  Stepped/reveal adjacencies: {len(stepped)}")
print(f"  Derived Fin Faces         : {len(FINS_DATA)}")
print(f"  Backed (1:1 expected)     : {min(len(stepped), len(FINS_DATA))}")

# Gov-2: Slenderness — flag sliver cells (discretisation quality)
print("\n[Gov-2] Slenderness / Sliver Check")
ars = [pl["dict"]["aspect_ratio"] for pl in PLATES_DATA]
slivers = [a for a in ars if a > 8]
print(f"  Mean aspect ratio:{sum(ars)/max(len(ars),1):.2f}  Max:{max(ars):.2f}  Slivers(>8):{len(slivers)}")

# Gov-3: Coverage per register
print("\n[Gov-3] Coverage per Register")
area_by_reg = defaultdict(float)
for pl in PLATES_DATA: area_by_reg[pl["dict"]["register_id"]] += pl["dict"]["area_m2"]
for r in regs:
    cov = area_by_reg[r] / (DW*DD)
    bar = chr(9608)*int(cov*20)
    print(f"  R{r} {bar:<20s} {area_by_reg[r]:8.1f} m2 = {cov:.1%}")

# Gov-4: Depth coherence (subdivision-depth distribution)
print("\n[Gov-4] Subdivision Depth Coherence")
depths = defaultdict(int)
for pl in PLATES_DATA: depths[pl["dict"]["subdiv_depth"]] += 1
for d in sorted(depths): print(f"  depth {d}: {depths[d]} cells")

# Gov-5: Register distribution
print("\n[Gov-5] Register Distribution")
for r in regs:
    solids = sum(1 for pl in PLATES_DATA if pl["dict"]["register_id"]==r and pl["dict"]["realisation"]=="solid")
    frames = by_reg[r] - solids
    print(f"  {pl_name(r):<10s} solid:{solids}  frame:{frames}")

# Gov-6: Adjacency graph metrics
print("\n[Gov-6] Adjacency Graph Metrics")
ds = Graph.DegreeSequence(g)
if ds: print(f"  Vertices:{len(ds)}  Avg degree:{sum(ds)/len(ds):.2f}  Max:{max(ds)}  Min:{min(ds)}")
try:
    bc = Graph.BetweennessCentrality(g)
    if bc:
        mx = max(bc); hub = Graph.Vertices(g)[bc.index(mx)]
        print(f"  Highest betweenness:{mx:.4f}  register={get_val(hub,'register')}")
except Exception as ex: print(f"  betweenness skipped ({ex})")

# Gov-7: Reveal inventory
print("\n[Gov-7] Reveal Inventory")
reveals = [f for f in FINS_DATA if f["dict"].get("reveal")]
tot_len = sum(f["dict"]["length_m"] for f in reveals)
max_step = max([f["dict"]["step_m"] for f in FINS_DATA], default=0)
print(f"  Reveals:{len(reveals)}  Total length:{tot_len:.1f} m  Max step:{max_step:.2f} m")

print("\n"+"="*58)
print("SUMMARY")
print("="*58)
print(f"  Cells:{len(cells)}  Fins:{len(fin_faces)}  Strata:{len(STRATA_DATA)}")
if ds: print(f"  Graph avg degree: {sum(ds)/len(ds):.2f}  components via Graph.ConnectedComponents")
print("="*58)
print("\nExtension points:")
print("  Topology.SelfMerge(cluster)         -> fuse touching plates into a CellComplex")
print("  CellComplex.ExternalFaces(cc)       -> facade / envelope extraction")
print("  Graph.MinimumSpanningTree(g)        -> primary structural circuit")
print("  Graph.CommunityPartition(g,key=...) -> register clustering")